<ColorPicker
  value={value.value}
  defaultFormat="rgb"
  showText={color => 'alpha ' + Math.round(color.toHsb().a * 100) + '%'}
  onFormatChange={nextFormat => {
    formatMode.value = nextFormat
  }}
  onChange={(_color, css) => {
    value.value = css || ''
  }}
/>

